1	import { rubbingTypeOrder, type RubbingType } from "@pirate-sea-race/content/objectives";
2	import { fnv1a64, hashState } from "../hash.js";
3	import { nextInt } from "../random.js";
4	import {
5	  requireId,
6	  requireInteger,
7	  sectorName,
8	  sectorOf,
9	  type CarrierSighting,
10	  type CarrierSnapshot,
11	  type CarrierSnapshotEntry,
12	  type IntelConfig,
13	  type IntelLeadReason,
14	  type IntelLeadTarget,
15	  type IntelMessage,
16	  type IntelMessageBody,
17	  type IntelPlayerState,
18	  type IntelPlayerView,
19	  type IntelState,
20	  type IntelStepResult,
21	  type IntelWorldView,
22	  type JournalRumor,
23	  type PendingSighting,
24	  type PendingSightingType,
25	  type SectorRef,
26	  type TargetedRumorOutcome,
27	  type TargetedRumorRequest,
28	  type TargetedRumorResult,
29	} from "./state.js";
30	
31	/** Lowest id by UTF-16 code units, independent of locale. */
32	function compareIds(a: string, b: string): number {
33	  return a < b ? -1 : a > b ? 1 : 0;
34	}
35	
36	function byTypeOrder(a: RubbingType, b: RubbingType): number {
37	  return rubbingTypeOrder(a) - rubbingTypeOrder(b);
38	}
39	
40	// ---------------------------------------------------------------------------------------------------------------------
41	// Reading the world view.
42	
43	interface WorldIndex {
44	  readonly tick: number;
45	  readonly players: ReadonlyMap<string, IntelPlayerView>;
46	  /** Each player's held types (carried or reserved in a duel), in type order. */
47	  readonly held: ReadonlyMap<string, readonly RubbingType[]>;
48	  readonly sources: readonly { readonly type: RubbingType; readonly island: number; readonly sector: number }[];
49	  readonly caches: readonly { readonly type: RubbingType; readonly sector: number }[];
50	  readonly carriers: readonly CarrierSnapshotEntry[];
51	}
52	
53	/** Refuses a malformed view: a tick not after `after`, duplicate ids, unknown types, islands or carriers, a doubled type. */
54	function readView(config: IntelConfig, view: IntelWorldView, after: number): WorldIndex {
55	  requireInteger(view.tick, "tick");
56	  if (view.tick <= after) throw new RangeError(`expected a tick after ${after}, got ${view.tick}`);
57	  const players = new Map<string, IntelPlayerView>();
58	  for (const player of view.players) {
59	    requireId(player.id, "player id");
60	    if (players.has(player.id)) throw new RangeError(`player ${player.id} appears twice`);
61	    requireInteger(player.x, `${player.id}.x`);
62	    requireInteger(player.y, `${player.id}.y`);
63	    players.set(player.id, player);
64	  }
65	  const ids = new Set<string>();
66	  const held = new Map<string, RubbingType[]>([...players.keys()].map((id) => [id, []]));
67	  const sources: { type: RubbingType; island: number; sector: number }[] = [];
68	  const caches: { type: RubbingType; sector: number }[] = [];
69	  const carriers: CarrierSnapshotEntry[] = [];
70	  for (const rubbing of view.rubbings) {
71	    requireId(rubbing.id, "rubbing id");
72	    if (ids.has(rubbing.id)) throw new RangeError(`rubbing ${rubbing.id} appears twice`);
73	    ids.add(rubbing.id);
74	    if (!config.types.includes(rubbing.type)) throw new RangeError(`rubbing ${rubbing.id} has a type outside the preset: ${String(rubbing.type)}`);
75	    const place = rubbing.place;
76	    switch (place.kind) {
77	      case "source":
78	        requireInteger(place.island, `${rubbing.id} island`);
79	        if (place.island < 0 || place.island >= config.islandNames.length) throw new RangeError(`rubbing ${rubbing.id} names an unknown island ${place.island}`);
80	        requireInteger(place.x, `${rubbing.id}.x`);
81	        requireInteger(place.y, `${rubbing.id}.y`);
82	        sources.push({ type: rubbing.type, island: place.island, sector: sectorOf(config, place) });
83	        break;
84	      case "cache":
85	        requireInteger(place.x, `${rubbing.id}.x`);
86	        requireInteger(place.y, `${rubbing.id}.y`);
87	        caches.push({ type: rubbing.type, sector: sectorOf(config, place) });
88	        break;
89	      case "carried":
90	      case "duel": {
91	        const holder = players.get(place.playerId);
92	        if (holder === undefined) throw new RangeError(`rubbing ${rubbing.id} is with ${String(place.playerId)}, who is not in the view`);
93	        const types = held.get(holder.id)!;
94	        if (types.includes(rubbing.type)) throw new RangeError(`player ${holder.id} holds two ${rubbing.type} rubbings`);
95	        types.push(rubbing.type);
96	        carriers.push({ sector: sectorOf(config, holder), type: rubbing.type, holder: holder.id });
97	        break;
98	      }
99	      default:
100	        throw new RangeError(`rubbing ${rubbing.id} has an unknown place`);
101	    }
102	  }
103	  for (const types of held.values()) types.sort(byTypeOrder);
104	  carriers.sort((a, b) => a.sector - b.sector || byTypeOrder(a.type, b.type) || compareIds(a.holder, b.holder));
105	  return { tick: view.tick, players, held, sources, caches, carriers };
106	}
107	
108	// ---------------------------------------------------------------------------------------------------------------------
109	// Planning a lead: sealed sources first, then caches, then a carrier sighting when every other copy is carried.
110	
111	type LeadPlan =
112	  | { readonly kind: "journal"; readonly options: readonly { readonly type: RubbingType; readonly target: IntelLeadTarget }[] }
113	  | {
114	      readonly kind: "carrier";
115	      /** The wanted types whose every copy is carried by someone else. */
116	      readonly types: readonly RubbingType[];
117	      /** Before the carrier reveal, one sighting message per player per snapshot. */
118	      readonly capped: boolean;
119	      /** Distinct (type, sector) pairs from the previous snapshot, the player's own entries left out. */
120	      readonly options: readonly { readonly type: RubbingType; readonly sector: number }[];
121	      readonly seenTick: number;
122	    }
123	  | { readonly kind: "none" };
124	
125	interface LeadHolder {
126	  readonly id: string;
127	  readonly journal: readonly JournalRumor[];
128	  readonly lastSightingBoundary: number;
129	}
130	
131	function sameTarget(a: IntelLeadTarget, b: IntelLeadTarget): boolean {
132	  return a.kind === "island" ? b.kind === "island" && a.island === b.island : b.kind === "sector" && a.sector === b.sector;
133	}
134	
135	function uniqueSorted(values: readonly number[]): number[] {
136	  return [...new Set(values)].sort((a, b) => a - b);
137	}
138	
139	function planLead(
140	  config: IntelConfig,
141	  world: WorldIndex,
142	  snapshots: readonly CarrierSnapshot[],
143	  player: LeadHolder,
144	  types: readonly RubbingType[],
145	): LeadPlan {
146	  const held = world.held.get(player.id) ?? [];
147	  const wanted = config.types.filter((type) => types.includes(type) && !held.includes(type));
148	  const active = player.journal.filter((rumor) => rumor.status === "active");
149	  const fresh = (type: RubbingType, target: IntelLeadTarget) => !active.some((rumor) => rumor.type === type && sameTarget(rumor.target, target));
150	
151	  const islands = wanted.flatMap((type) =>
152	    uniqueSorted(world.sources.filter((source) => source.type === type).map((source) => source.island))
153	      .map((island) => ({ type, target: { kind: "island", island } as const }))
154	      .filter((option) => fresh(option.type, option.target)),
155	  );
156	  if (islands.length > 0) return { kind: "journal", options: islands };
157	  const sectors = wanted.flatMap((type) =>
158	    uniqueSorted(world.caches.filter((cache) => cache.type === type).map((cache) => cache.sector))
159	      .map((sector) => ({ type, target: { kind: "sector", sector } as const }))
160	      .filter((option) => fresh(option.type, option.target)),
161	  );
162	  if (sectors.length > 0) return { kind: "journal", options: sectors };
163	
164	  const carried = wanted.filter(
165	    (type) =>
166	      !world.sources.some((source) => source.type === type) &&
167	      !world.caches.some((cache) => cache.type === type) &&
168	      world.carriers.some((carrier) => carrier.type === type && carrier.holder !== player.id),
169	  );
170	  if (carried.length === 0) return { kind: "none" };
171	  const newest = snapshots.at(-1);
172	  const older = snapshots.length === 2 ? snapshots[0]! : undefined;
173	  const capped = world.tick < config.carrierRevealTick && newest !== undefined && player.lastSightingBoundary === newest.boundary;
174	  const options: { type: RubbingType; sector: number }[] = [];
175	  for (const entry of older?.entries ?? []) {
176	    if (entry.holder === player.id || !carried.includes(entry.type)) continue;
177	    if (!options.some((option) => option.type === entry.type && option.sector === entry.sector)) options.push({ type: entry.type, sector: entry.sector });
178	  }
179	  options.sort((a, b) => byTypeOrder(a.type, b.type) || a.sector - b.sector);
180	  return { kind: "carrier", types: carried, capped, options, seenTick: older?.tick ?? -1 };
181	}
182	
183	interface CoverageHolder extends LeadHolder {
184	  readonly pending: PendingSighting | null;
185	}
186	
187	/**
188	 * Free coverage: whether a purchase of `type` would only buy what the player gets for free anyway. Only a type whose
189	 * sole eligible target is a carrier qualifies, by `planLead`, the eligibility rumor generation uses (sources, then
190	 * caches, then carriers), and then when either holds:
191	 * (a) the minute-28 reveal has happened: the free 30 s broadcast is fresher than a paid sighting of the older snapshot;
192	 * (b) the type is in the player's pending set after the gather phase: the next boundary delivers it free.
193	 */
194	function coveredFree(config: IntelConfig, world: WorldIndex, snapshots: readonly CarrierSnapshot[], holder: CoverageHolder, type: RubbingType): boolean {
195	  if (planLead(config, world, snapshots, holder, [type]).kind !== "carrier") return false;
196	  return world.tick >= config.carrierRevealTick || (holder.pending?.types.some((waiting) => waiting.type === type) ?? false);
197	}
198	
199	/**
200	 * The one free-coverage predicate of the step (`covered` answers in phase 3) and of the UI
201	 * (`targetedRumorAvailability`), read from the state after its last step and the world view of that tick or a later one:
202	 * `covered` when a purchase of `type` by `playerId` would be free coverage (`coveredFree`), otherwise null.
203	 */
204	export function freeCoverage(config: IntelConfig, state: IntelState, view: IntelWorldView, playerId: string, type: RubbingType): "covered" | null {
205	  const world = readView(config, view, state.tick - 1);
206	  if (!state.started || !world.players.has(playerId) || !config.types.includes(type)) return null;
207	  const player = state.players.find((candidate) => candidate.id === playerId) ?? { id: playerId, journal: [], lastSightingBoundary: -1, pending: null };
208	  return coveredFree(config, world, state.snapshots, player, type) ? "covered" : null;
209	}
210	
211	/**
212	 * What buying a targeted rumor for `type` would yield for `playerId` now, from the state after its last step and the
213	 * world view of that tick or a later one, without drawing: `covered` by `freeCoverage`, otherwise the lead it would
214	 * buy. A step on a later tick can differ only if it first crosses a snapshot boundary. A free trigger of the same
215	 * player and type in that step makes the purchase `covered` instead.
216	 */
217	export function targetedRumorAvailability(
218	  config: IntelConfig,
219	  state: IntelState,
220	  view: IntelWorldView,
221	  playerId: string,
222	  type: RubbingType,
223	): Exclude<TargetedRumorResult, "duplicate"> {
224	  const world = readView(config, view, state.tick - 1);
225	  if (!state.started || !world.players.has(playerId) || !config.types.includes(type)) return "none";
226	  if (freeCoverage(config, state, view, playerId, type) !== null) return "covered";
227	  const player = state.players.find((candidate) => candidate.id === playerId) ?? { id: playerId, journal: [], lastSightingBoundary: -1 };
228	  return targetedResult(planLead(config, world, state.snapshots, player, [type]));
229	}
230	
231	function targetedResult(plan: LeadPlan): Exclude<TargetedRumorResult, "duplicate" | "covered"> {
232	  if (plan.kind === "journal") return "rumor";
233	  if (plan.kind === "none") return "none";
234	  if (plan.capped) return "capped";
235	  return plan.options.length > 0 ? "sighting" : "none";
236	}
237	
238	// ---------------------------------------------------------------------------------------------------------------------
239	// The three lead phases of a step: gather every trigger by (player, type), decide each entry, answer the requests.
240	
241	/** A trigger for a lead: a free one (a loss, a journal replacement, a pending type at a boundary) or a paid request. */
242	export type LeadTrigger =
243	  | { readonly playerId: string; readonly type: RubbingType; readonly free: PendingSightingType }
244	  | { readonly playerId: string; readonly type: RubbingType; readonly requestId: string };
245	
246	/** One (player, type) of a step: the free trigger it keeps, if any, and the ids of its requests, sorted. */
247	export interface LeadEntry {
248	  readonly playerId: string;
249	  readonly type: RubbingType;
250	  readonly free: PendingSightingType | null;
251	  readonly requestIds: readonly string[];
252	}
253	
254	/** The earliest free trigger wins, then `fresh` before `replacement`, so the arrival order never picks the reason. */
255	function compareFree(a: PendingSightingType, b: PendingSightingType): number {
256	  return a.tick - b.tick || (a.reason === b.reason ? 0 : a.reason === "fresh" ? -1 : 1);
257	}
258	
259	function compareEntries(a: { playerId: string; type: RubbingType }, b: { playerId: string; type: RubbingType }): number {
260	  return compareIds(a.playerId, b.playerId) || byTypeOrder(a.type, b.type);
261	}
262	
263	/** Phase 1: the step's triggers as a set keyed by (player, type), sorted by player id then type order. */
264	export function gatherLeads(triggers: readonly LeadTrigger[]): LeadEntry[] {
265	  const entries = new Map<string, { playerId: string; type: RubbingType; free: PendingSightingType | null; requestIds: Set<string> }>();
266	  for (const trigger of triggers) {
267	    const key = `${trigger.playerId}\u0000${trigger.type}`;
268	    let entry = entries.get(key);
269	    if (entry === undefined) entries.set(key, (entry = { playerId: trigger.playerId, type: trigger.type, free: null, requestIds: new Set() }));
270	    if ("free" in trigger) {
271	      if (entry.free === null || compareFree(trigger.free, entry.free) < 0) entry.free = trigger.free;
272	    } else entry.requestIds.add(trigger.requestId);
273	  }
274	  return [...entries.values()]
275	    .map(({ playerId, type, free, requestIds }) => ({ playerId, type, free, requestIds: [...requestIds].sort(compareIds) }))
276	    .sort(compareEntries);
277	}
278	
279	/**
280	 * What one (player, type) entry got: `free` when a free trigger's (or the start's) rumor or sighting gave the player
281	 * that type, `covered` when only its requests asked and free coverage (`freeCoverage`) holds, so nothing is sent,
282	 * `rumor` or `sighting` when only its requests asked, otherwise `capped` or `none`.
283	 */
284	export type LeadDelivery = "free" | "covered" | "rumor" | "sighting" | "capped" | "none";
285	
286	/** One decided lead message, in decision order: per player by id, the start first, then its entries in type order. */
287	export type DecidedLead =
288	  | { readonly kind: "rumor"; readonly playerId: string; readonly type: RubbingType; readonly target: IntelLeadTarget; readonly reason: IntelLeadReason }
289	  | { readonly kind: "no-lead"; readonly playerId: string; readonly type: RubbingType; readonly reason: IntelLeadReason };
290	
291	export interface LeadDecisions {
292	  readonly leads: readonly DecidedLead[];
293	  /** At most one sighting message per player, by player id, its types in type order. */
294	  readonly sightings: readonly { readonly playerId: string; readonly seenTick: number; readonly sightings: readonly CarrierSighting[] }[];
295	  readonly deliveries: readonly (LeadEntry & { readonly delivery: LeadDelivery })[];
296	  /** The pending sighting of each player with an entry, after the step. */
297	  readonly pending: ReadonlyMap<string, PendingSighting | null>;
298	}
299	
300	type DecisionHolder = CoverageHolder;
301	
302	/** An integer in [0, bound) from a generator keyed by the seed and a decision's key, not by any other decision. */
303	function keyedDraw(seed: number, key: string, bound: number): number {
304	  return nextInt(Number.parseInt(fnv1a64(`${seed >>> 0}\u0000${key}`).slice(8), 16) >>> 0, bound).value;
305	}
306	
307	/**
308	 * Phase 2: decides each entry from the world view and the older snapshot. A starting player's start rumor comes first.
309	 * Each draw is keyed by (seed, tick, player, type), or by the older snapshot's tick for a sighting's sector among the
310	 * sorted candidates, so neither the order of the entries nor any other player's entries change a decision.
311	 */
312	function decide(
313	  config: IntelConfig,
314	  world: WorldIndex,
315	  snapshots: readonly CarrierSnapshot[],
316	  seed: number,
317	  holders: ReadonlyMap<string, DecisionHolder>,
318	  entries: readonly LeadEntry[],
319	  starting: ReadonlySet<string>,
320	): LeadDecisions {
321	  const tick = world.tick;
322	  const leads: DecidedLead[] = [];
323	  const sightings: { playerId: string; seenTick: number; sightings: CarrierSighting[] }[] = [];
324	  const deliveries: (LeadEntry & { delivery: LeadDelivery })[] = [];
325	  const pending = new Map<string, PendingSighting | null>();
326	  const sorted = [...entries].sort(compareEntries);
327	  const playerIds = [...new Set([...starting, ...sorted.map((entry) => entry.playerId)])].sort(compareIds);
328	  for (const playerId of playerIds) {
329	    const known = holders.get(playerId);
330	    const journal: JournalRumor[] = [...(known?.journal ?? [])];
331	    const holder: LeadHolder = { id: playerId, journal, lastSightingBoundary: known?.lastSightingBoundary ?? -1 };
332	    const held = world.held.get(playerId) ?? [];
333	    const rumor = (plan: Extract<LeadPlan, { kind: "journal" }>, key: string, reason: IntelLeadReason): RubbingType => {
334	      const { type, target } = plan.options[keyedDraw(seed, `${tick}\u0000${playerId}\u0000${key}`, plan.options.length)]!;
335	      journal.push({ entry: journal.length + 1, type, target, reason, tick, status: "active", closedTick: null });
336	      leads.push({ kind: "rumor", playerId, type, target, reason });
337	      return type;
338	    };
339	    // A starting rumor points at a source or a cache of any missing type, never at a carrier; otherwise a no-lead.
340	    let startType: RubbingType | null = null;
341	    if (starting.has(playerId)) {
342	      const plan = planLead(config, world, snapshots, holder, config.types);
343	      if (plan.kind === "journal") startType = rumor(plan, "start", "start");
344	      else {
345	        const lacking = config.types.filter((type) => !held.includes(type));
346	        if (lacking.length > 0) leads.push({ kind: "no-lead", playerId, type: lacking[0]!, reason: "start" });
347	      }
348	    }
349	    const mine = sorted.filter((entry) => entry.playerId === playerId);
350	    const carried: LeadEntry[] = [];
351	    for (const entry of mine) {
352	      if (entry.type === startType) {
353	        deliveries.push({ ...entry, delivery: "free" });
354	        continue;
355	      }
356	      // A purchase of what the broadcast or the pending set gives for free is covered: nothing sent, nothing charged.
357	      if (entry.free === null && coveredFree(config, world, snapshots, { ...holder, pending: known?.pending ?? null }, entry.type)) {
358	        deliveries.push({ ...entry, delivery: "covered" });
359	        continue;
360	      }
361	      const plan = planLead(config, world, snapshots, holder, [entry.type]);
362	      if (plan.kind === "journal") {
363	        rumor(plan, entry.type, entry.free?.reason ?? "targeted");
364	        deliveries.push({ ...entry, delivery: entry.free !== null ? "free" : "rumor" });
365	      } else if (plan.kind === "carrier") carried.push(entry);
366	      else {
367	        if (entry.free !== null && !held.includes(entry.type)) leads.push({ kind: "no-lead", playerId, type: entry.type, reason: entry.free.reason });
368	        deliveries.push({ ...entry, delivery: "none" });
369	      }
370	    }
371	    if (mine.length === 0) continue;
372	    // One sighting decision for the player: uncapped, one message lists every type the older snapshot can answer.
373	    let sent: RubbingType[] = [];
374	    let capped = false;
375	    if (carried.length > 0) {
376	      const plan = planLead(config, world, snapshots, holder, carried.map((entry) => entry.type));
377	      if (plan.kind !== "carrier") throw new Error(`the sighting types of ${playerId} no longer need a sighting`);
378	      capped = plan.capped;
379	      if (!capped) sent = carried.map((entry) => entry.type).filter((type) => plan.options.some((option) => option.type === type));
380	      if (sent.length > 0) {
381	        sightings.push({
382	          playerId,
383	          seenTick: plan.seenTick,
384	          sightings: sent.map((type) => {
385	            const entry = carried.find((candidate) => candidate.type === type)!;
386	            const sectors = plan.options.filter((option) => option.type === type).map((option) => option.sector);
387	            const sector = sectors[keyedDraw(seed, `${plan.seenTick}\u0000${playerId}\u0000${type}`, sectors.length)]!;
388	            return { type, reason: entry.free?.reason ?? "targeted", sector, name: sectorName(config, sector) };
389	          }),
390	        });
391	      }
392	    }
393	    for (const entry of carried) {
394	      deliveries.push({ ...entry, delivery: sent.includes(entry.type) ? (entry.free !== null ? "free" : "sighting") : capped ? "capped" : "none" });
395	    }
396	    // The free types not sent keep waiting in the one pending set; a paid type is never queued.
397	    const kept = (known?.pending?.types ?? []).filter((waiting) => !sent.includes(waiting.type));
398	    for (const entry of carried) {
399	      if (entry.free !== null && !sent.includes(entry.type) && !kept.some((waiting) => waiting.type === entry.type)) kept.push(entry.free);
400	    }
401	    kept.sort((a, b) => byTypeOrder(a.type, b.type));
402	    pending.set(playerId, kept.length > 0 ? { types: kept } : null);
403	  }
404	  deliveries.sort(compareEntries);
405	  return { leads, sightings, deliveries, pending };
406	}
407	
408	/**
409	 * Phase 2 from outside a step: decides `entries` against a state whose snapshots are current (as after a step) and the
410	 * world view of that tick or a later one. `starting` lists the players whose start rumor is decided too.
411	 */
412	export function decideLeads(
413	  config: IntelConfig,
414	  state: IntelState,
415	  view: IntelWorldView,
416	  entries: readonly LeadEntry[],
417	  starting: readonly string[] = [],
418	): LeadDecisions {
419	  const world = readView(config, view, state.tick - 1);
420	  return decide(config, world, state.snapshots, state.rng, new Map(state.players.map((player) => [player.id, player])), entries, new Set(starting));
421	}
422	
423	/**
424	 * Phase 3: the requests of each (player, type), by request id. A free delivery or free coverage covers them all; a
425	 * paid one goes to the first and covers the rest; with nothing delivered, all get the same `capped` or `none`. Only
426	 * `rumor` and `sighting` are charged, and one player's requests never change another's.
427	 */
428	export function answerRequests(deliveries: readonly { readonly requestIds: readonly string[]; readonly delivery: LeadDelivery }[]): Map<string, TargetedRumorResult> {
429	  const results = new Map<string, TargetedRumorResult>();
430	  for (const { requestIds, delivery } of deliveries) {
431	    [...requestIds].sort(compareIds).forEach((requestId, index) => {
432	      results.set(requestId, delivery === "free" ? "covered" : delivery === "rumor" || delivery === "sighting" ? (index === 0 ? delivery : "covered") : delivery);
433	    });
434	  }
435	  return results;
436	}
437	
438	// ---------------------------------------------------------------------------------------------------------------------
439	// The step.
440	
441	interface WorkingPlayer {
442	  id: string;
443	  held: readonly RubbingType[];
444	  journal: JournalRumor[];
445	  routeActive: boolean;
446	  routeEver: boolean;
447	  lastSightingBoundary: number;
448	  pending: PendingSighting | null;
449	}
450	
451	function working(player: IntelPlayerState): WorkingPlayer {
452	  return { ...player, journal: [...player.journal] };
453	}
454	
455	function frozen(player: WorkingPlayer): IntelPlayerState {
456	  return {
457	    id: player.id,
458	    held: [...player.held],
459	    journal: player.journal,
460	    routeActive: player.routeActive,
461	    routeEver: player.routeEver,
462	    lastSightingBoundary: player.lastSightingBoundary,
463	    pending: player.pending,
464	  };
465	}
466	
467	function sectorRef(config: IntelConfig, sector: number): SectorRef {
468	  return { sector, name: sectorName(config, sector) };
469	}
470	
471	/** The latest boundary `origin + k × interval` at or before `tick`, or -1 before `origin`. */
472	function boundaryIndex(tick: number, origin: number, interval: number): number {
473	  return tick < origin ? -1 : Math.floor((tick - origin) / interval);
474	}
475	
476	/**
477	 * One world tick of the information rules, in a fixed order:
478	 *
479	 * 1. Crossing a carrier boundary (every interval from control start) takes a snapshot of the carried copies; the
480	 *    latest two are kept.
481	 * 2. Per player, by id: the diff of held types resolves rumors for types gained; rumors whose target was emptied go
482	 *    stale; a completed or broken full set announces the final sector and sends or suspends the route.
483	 * 3. The leads, in three phases. Gather: every trigger joins a set keyed by (player, type): a type lost, a stale
484	 *    rumor's replacement, a pending type at a boundary, a targeted request. Decide: per player by id, a starting
485	 *    rumor first (never a sighting), then each entry in type order: a journal rumor, a no-lead, or its type joins the
486	 *    player's one sighting decision (one message listing every type the older snapshot can answer, or, capped, the free
487	 *    types wait as the one pending set); a purchase that `freeCoverage` covers sends nothing. Answer: each (player,
488	 *    type)'s requests by request id (`answerRequests`).
489	 * 4. The minute-20 sector reveal and the minute-28 carrier broadcasts, when their boundary was crossed.
490	 *
491	 * Every draw is keyed by (seed, tick, player, type), so no decision depends on the order of the triggers, requests or
492	 * view arrays. Boundaries fire when crossed since the last processed tick, so a skipped tick never loses one. Before
493	 * control start only the held types are tracked, and no message is sent. The input state is never mutated.
494	 */
495	export function stepIntel(
496	  config: IntelConfig,
497	  state: IntelState,
498	  view: IntelWorldView,
499	  requests: readonly TargetedRumorRequest[] = [],
500	): IntelStepResult {
501	  const world = readView(config, view, state.tick);
502	  for (const request of requests) {
503	    requireId(request.requestId, "request id");
504	    requireId(request.playerId, "request player id");
505	    if (typeof request.type !== "string") throw new RangeError(`request ${request.requestId} has no type`);
506	  }
507	  const tick = world.tick;
508	  const messages: IntelMessage[] = [];
509	  const toPlayer = (playerId: string, body: IntelMessageBody) => messages.push({ to: { kind: "player", playerId }, body });
510	  const toEveryone = (body: IntelMessageBody) => messages.push({ to: { kind: "everyone" }, body });
511	
512	  const previous = new Map(state.players.map((player) => [player.id, player]));
513	  const players: WorkingPlayer[] = [...world.players.keys()].sort(compareIds).map((id) => {
514	    const known = previous.get(id);
515	    return known
516	      ? working(known)
517	      : { id, held: [], journal: [], routeActive: false, routeEver: false, lastSightingBoundary: -1, pending: null };
518	  });
519	
520	  // Requests: an id seen before is a duplicate and touches nothing. A new id listed twice in one batch is recorded
521	  // once, for its lowest (player, type), so the listing order never picks it; the others are duplicates.
522	  const seen = new Set(state.requestIds);
523	  const chosen = new Map<string, number>();
524	  requests.forEach((request, index) => {
525	    if (seen.has(request.requestId)) return;
526	    const other = chosen.get(request.requestId);
527	    if (other === undefined || compareEntries(request, requests[other]!) < 0) chosen.set(request.requestId, index);
528	  });
529	  const outcomes = new Map<number, TargetedRumorResult>();
530	  const accepted: { index: number; request: TargetedRumorRequest }[] = [];
531	  requests.forEach((request, index) => {
532	    if (chosen.get(request.requestId) === index) accepted.push({ index, request });
533	    else outcomes.set(index, "duplicate");
534	  });
535	  const requestIds = chosen.size === 0 ? state.requestIds : [...state.requestIds, ...chosen.keys()].sort(compareIds);
536	  const answer = (): TargetedRumorOutcome[] => requests.map((request, index) => ({ requestId: request.requestId, result: outcomes.get(index)! }));
537	
538	  if (tick < config.controlStartTick) {
539	    for (const { index } of accepted) outcomes.set(index, "none");
540	    for (const player of players) player.held = world.held.get(player.id)!;
541	    return { state: { ...state, tick, players: players.map(frozen), requestIds }, messages, outcomes: answer() };
542	  }
543	
544	  // 1. Carrier snapshots.
545	  let snapshots = state.snapshots;
546	  const boundary = boundaryIndex(tick, config.controlStartTick, config.carrierIntervalTicks);
547	  const crossedBoundary = boundary > (snapshots.at(-1)?.boundary ?? -1);
548	  if (crossedBoundary) snapshots = [...snapshots, { boundary, tick, entries: world.carriers }].slice(-2);
549	
550	  // 2. Players; their free triggers are gathered for step 3.
551	  const triggers: LeadTrigger[] = [];
552	  const starting = new Set<string>();
553	  const startCrossed = !state.started;
554	  let finalAnnounced = state.finalSectorAnnounced;
555	  for (const player of players) {
556	    const held = world.held.get(player.id)!;
557	    if (startCrossed || !previous.has(player.id)) {
558	      player.held = held;
559	      starting.add(player.id);
560	    } else {
561	      const gained = held.filter((type) => !player.held.includes(type));
562	      const lost = player.held.filter((type) => !held.includes(type));
563	      player.held = held;
564	      // Types obtained retire their rumors quietly and cancel their deferred sightings.
565	      player.journal = player.journal.map((rumor) => {
566	        if (rumor.status !== "active" || !gained.includes(rumor.type)) return rumor;
567	        toPlayer(player.id, { kind: "rumor-resolved", tick, entry: rumor.entry, type: rumor.type });
568	        return { ...rumor, status: "resolved", closedTick: tick };
569	      });
570	      const stillWanted = player.pending?.types.filter((pending) => !held.includes(pending.type)) ?? [];
571	      player.pending = stillWanted.length > 0 ? { types: stillWanted } : null;
572	      // At a boundary the pending types are decided again with this step's other triggers. A type the player has
573	      // bought a live rumor for since is dropped quietly: no sighting and no no-lead.
574	      if (crossedBoundary) {
575	        player.pending = null;
576	        for (const pending of stillWanted) {
577	          if (player.journal.some((rumor) => rumor.status === "active" && rumor.type === pending.type)) continue;
578	          triggers.push({ playerId: player.id, type: pending.type, free: pending });
579	        }
580	      }
581	      // §11: a free fresh rumor for each type lost. Entering a duel is no loss: reserved copies still count as held.
582	      for (const type of lost) triggers.push({ playerId: player.id, type, free: { type, reason: "fresh", tick } });
583	    }
584	
585	    // Journal rumors whose island or cache sector no longer holds the type go stale, then get a replacement.
586	    player.journal = player.journal.map((rumor) => {
587	      if (rumor.status !== "active") return rumor;
588	      const { target } = rumor;
589	      const holds =
590	        target.kind === "island"
591	          ? world.sources.some((source) => source.type === rumor.type && source.island === target.island)
592	          : world.caches.some((cache) => cache.type === rumor.type && cache.sector === target.sector);
593	      if (holds) return rumor;
594	      toPlayer(player.id, { kind: "rumor-stale", tick, entry: rumor.entry, type: rumor.type });
595	      triggers.push({ playerId: player.id, type: rumor.type, free: { type: rumor.type, reason: "replacement", tick } });
596	      return { ...rumor, status: "stale", closedTick: tick };
597	    });
598	
599	    // §5: the first full set announces the final sector to everyone; each holder gets the route while the set is whole.
600	    const complete = config.types.every((type) => held.includes(type));
601	    if (complete && !player.routeActive) {
602	      if (!finalAnnounced) {
603	        finalAnnounced = true;
604	        const sector = sectorOf(config, config.finalIsland);
605	        toEveryone({ kind: "final-sector", tick, sector, name: sectorName(config, sector) });
606	      }
607	      toPlayer(player.id, { kind: "final-route", tick, x: config.finalIsland.x, y: config.finalIsland.y, restored: player.routeEver });
608	      player.routeActive = true;
609	      player.routeEver = true;
610	    } else if (!complete && player.routeActive) {
611	      toPlayer(player.id, { kind: "final-route-inactive", tick });
612	      player.routeActive = false;
613	    }
614	  }
615	
616	  // 3. Leads. Gather: targeted requests (§11) join the free triggers by (player, type).
617	  const byId = new Map(players.map((player) => [player.id, player]));
618	  const requestIndex = new Map<string, number>();
619	  for (const { index, request } of accepted) {
620	    if (!byId.has(request.playerId) || !config.types.includes(request.type)) outcomes.set(index, "none");
621	    else {
622	      requestIndex.set(request.requestId, index);
623	      triggers.push({ playerId: request.playerId, type: request.type, requestId: request.requestId });
624	    }
625	  }
626	  const entries = gatherLeads(triggers);
627	  // Decide.
628	  const decided = decide(config, world, snapshots, state.rng, byId, entries, starting);
629	  for (const lead of decided.leads) {
630	    const player = byId.get(lead.playerId)!;
631	    if (lead.kind === "no-lead") {
632	      toPlayer(player.id, { kind: "no-lead", tick, type: lead.type, reason: lead.reason });
633	      continue;
634	    }
635	    const { type, target, reason } = lead;
636	    const entry = player.journal.length + 1;
637	    player.journal.push({ entry, type, target, reason, tick, status: "active", closedTick: null });
638	    toPlayer(player.id, {
639	      kind: "rumor",
640	      tick,
641	      entry,
642	      type,
643	      reason,
644	      target:
645	        target.kind === "island"
646	          ? { kind: "island", island: target.island, name: config.islandNames[target.island]! }
647	          : { kind: "sector", sector: target.sector, name: sectorName(config, target.sector) },
648	    });
649	  }
650	  // A sighting message spends the player's sighting for this snapshot.
651	  for (const { playerId, seenTick, sightings } of decided.sightings) {
652	    byId.get(playerId)!.lastSightingBoundary = snapshots.at(-1)!.boundary;
653	    toPlayer(playerId, { kind: "carrier-sighting", tick, seenTick, sightings });
654	  }
655	  for (const [playerId, pending] of decided.pending) byId.get(playerId)!.pending = pending;
656	  // Answer.
657	  for (const [requestId, result] of answerRequests(decided.deliveries)) outcomes.set(requestIndex.get(requestId)!, result);
658	
659	  // 4. Timed reveals (§2).
660	  let sectorRevealed = state.sectorRevealed;
661	  if (!sectorRevealed && tick >= config.sectorRevealTick) {
662	    sectorRevealed = true;
663	    toEveryone({
664	      kind: "sector-reveal",
665	      tick,
666	      sources: uniqueSorted(world.sources.map((source) => source.sector)).map((sector) => sectorRef(config, sector)),
667	      caches: uniqueSorted(world.caches.map((cache) => cache.sector)).map((sector) => sectorRef(config, sector)),
668	    });
669	  }
670	  let lastCarrierBroadcast = state.lastCarrierBroadcast;
671	  const broadcast = boundaryIndex(tick, config.carrierRevealTick, config.carrierIntervalTicks);
672	  if (broadcast > lastCarrierBroadcast) {
673	    lastCarrierBroadcast = broadcast;
674	    const newest = snapshots.at(-1)!;
675	    const carriers: (SectorRef & { type: RubbingType })[] = [];
676	    for (const entry of newest.entries) {
677	      if (!carriers.some((carrier) => carrier.sector === entry.sector && carrier.type === entry.type)) {
678	        carriers.push({ ...sectorRef(config, entry.sector), type: entry.type });
679	      }
680	    }
681	    toEveryone({ kind: "carrier-report", tick, seenTick: newest.tick, carriers });
682	  }
683	
684	  return {
685	    state: {
686	      tick,
687	      rng: state.rng,
688	      started: true,
689	      players: players.map(frozen),
690	      snapshots,
691	      finalSectorAnnounced: finalAnnounced,
692	      sectorRevealed,
693	      lastCarrierBroadcast,
694	      requestIds,
695	    },
696	    messages,
697	    outcomes: answer(),
698	  };
699	}
700	
701	export interface IntelReplayTick {
702	  readonly view: IntelWorldView;
703	  readonly requests?: readonly TargetedRumorRequest[];
704	}
705	
706	export interface IntelReplay {
707	  readonly state: IntelState;
708	  readonly messages: readonly IntelMessage[];
709	  readonly outcomes: readonly TargetedRumorOutcome[];
710	  readonly hash: string;
711	}
712	
713	/** Steps a sequence of views from a state, collecting every message and outcome; `hash` is the final `hashState`. */
714	export function replayIntel(config: IntelConfig, state: IntelState, ticks: readonly IntelReplayTick[]): IntelReplay {
715	  let current = state;
716	  const messages: IntelMessage[] = [];
717	  const outcomes: TargetedRumorOutcome[] = [];
718	  for (const { view, requests } of ticks) {
719	    const stepped = stepIntel(config, current, view, requests ?? []);
720	    current = stepped.state;
721	    messages.push(...stepped.messages);
722	    outcomes.push(...stepped.outcomes);
723	  }
724	  return { state: current, messages, outcomes, hash: hashState(current) };
725	}
